var p=GameObject.FindGameObjectWithTag("Player");var c=Camera.main;var rs=UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(r=>r.name=="Ground"||r.bounds.Contains(p.transform.position)||r.name.Contains("Dark")||r.name.Contains("Vision")).Take(30).Select(r=>new{r.name,r.enabled,active=r.gameObject.activeInHierarchy,layer=r.gameObject.layer,bounds=r.bounds.ToString(),materials=r.sharedMaterials.Where(m=>m!=null).Select(m=>new{m.name,shader=m.shader.name})});return Newtonsoft.Json.JsonConvert.SerializeObject(new{camera=c.transform.position.ToString(),c.cullingMask,c.farClipPlane,c.nearClipPlane,rect=c.rect.ToString(),player=p.transform.position.ToString(),renderers=rs});
